from collections import Counter
# print components of test and their boxes
h,w=len(tg),len(tg[0]); bg=Counter(v for row in tg for v in row).most_common(1)[0][0]; seen=set(); info=[]
for r in range(h):
 for c in range(w):
  color=tg[r][c]
  if color==bg or (r,c) in seen: continue
  st=[(r,c)]; seen.add((r,c)); cells=[]
  while st:
   y,x=st.pop(); cells.append((y,x))
   for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and tg[yy][xx]==color: seen.add((yy,xx));st.append((yy,xx))
  if len(cells)>=3:
   info.append((color,len(cells),(min(y for y,x in cells),min(x for y,x in cells),max(y for y,x in cells),max(x for y,x in cells))))
print(bg,info)
